    private void rememberColor(int color){String value=Integer.toHexString(color);String old=DataStore.prefs(this).getString("widget_recent_colors","");StringBuilder out=new StringBuilder(value);int count=1;for(String item:old.split(",")){if(item.isEmpty()||item.equalsIgnoreCase(value))continue;if(count>=8)break;out.append(',').append(item);count++;}DataStore.prefs(this).edit().putString("widget_recent_colors",out.toString()).apply();}
    private int[] recentColors(){String saved=DataStore.prefs(this).getString("widget_recent_colors","");java.util.ArrayList<Integer> values=new java.util.ArrayList<>();for(String part:saved.split(",")){try{if(!part.isEmpty())values.add((int)Long.parseLong(part,16));}catch(Exception ignored){}}int[] colors=new int[values.size()];for(int i=0;i<colors.length;i++)colors[i]=values.get(i);return colors;}
    private void openColorPicker(boolean foreground){openColorPicker(foreground?0:1);}
    private void openColorPicker(int target){final float[] hsv=new float[3];Color.colorToHSV(target==0?textColor:background,hsv);final int[] selected={Color.HSVToColor(hsv)};LinearLayout form=col();form.setPadding(dp(20),dp(6),dp(20),dp(8));TextView sample=txt("Color preview",12,Color.WHITE,true);sample.setGravity(Gravity.CENTER);sample.setBackground(shape(selected[0],16,false));form.addView(sample,new LinearLayout.LayoutParams(-1,dp(42)));SeekBar hue=new SeekBar(this),saturation=new SeekBar(this),brightness=new SeekBar(this);hue.setMax(359);hue.setProgress(Math.round(hsv[0]));saturation.setMax(100);saturation.setProgress(Math.round(hsv[1]*100));brightness.setMax(100);brightness.setProgress(Math.round(hsv[2]*100));for(SeekBar bar:new SeekBar[]{hue,saturation,brightness}){bar.setProgressTintList(ColorStateList.valueOf(DataStore.accent(this)));bar.setThumbTintList(ColorStateList.valueOf(DataStore.accent(this)));}form.addView(txt("Hue",11,dark?0xffb9c8c3:0xff566b65,true),new LinearLayout.LayoutParams(-1,dp(24)));form.addView(hue,new LinearLayout.LayoutParams(-1,dp(34)));form.addView(txt("Saturation",11,dark?0xffb9c8c3:0xff566b65,true),new LinearLayout.LayoutParams(-1,dp(24)));form.addView(saturation,new LinearLayout.LayoutParams(-1,dp(34)));form.addView(txt("Brightness",11,dark?0xffb9c8c3:0xff566b65,true),new LinearLayout.LayoutParams(-1,dp(24)));form.addView(brightness,new LinearLayout.LayoutParams(-1,dp(34)));int[] recent=recentColors();if(recent.length>0){form.addView(txt("Recent",11,dark?0xffb9c8c3:0xff566b65,true),new LinearLayout.LayoutParams(-1,dp(25)));LinearLayout recents=row();form.addView(recents,new LinearLayout.LayoutParams(-1,dp(34)));for(int color:recent){View dot=new View(this);GradientDrawable shape=new GradientDrawable();shape.setShape(GradientDrawable.OVAL);shape.setColor(color);shape.setStroke(dp(1),0xff899b95);dot.setBackground(shape);LinearLayout holder=row();holder.setGravity(Gravity.CENTER);holder.addView(dot,new LinearLayout.LayoutParams(dp(25),dp(25)));recents.addView(holder,new LinearLayout.LayoutParams(0,dp(34),1));holder.setContentDescription("Recent color");holder.setOnClickListener(v->{Color.colorToHSV(color,hsv);selected[0]=color;updateColorSample(sample,color);hue.setProgress(Math.round(hsv[0]));saturation.setProgress(Math.round(hsv[1]*100));brightness.setProgress(Math.round(hsv[2]*100));});}}SeekBar.OnSeekBarChangeListener listener=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){hsv[0]=hue.getProgress();hsv[1]=saturation.getProgress()/100f;hsv[2]=brightness.getProgress()/100f;selected[0]=Color.HSVToColor(hsv);updateColorSample(sample,selected[0]);}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}};hue.setOnSeekBarChangeListener(listener);saturation.setOnSeekBarChangeListener(listener);brightness.setOnSeekBarChangeListener(listener);dialogBuilder().setTitle(target==0?"Text color":"Panel color").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Use color",(dialog,which)->{applyColor(selected[0],target==0);}).show();}
    private void updateColorSample(TextView sample,int color){sample.setBackground(shape(color,16,false));sample.setTextColor(contrastingColor(color));}
    private int contrastingColor(int color){return (0.299*Color.red(color)+0.587*Color.green(color)+0.114*Color.blue(color))>150?Color.BLACK:Color.WHITE;}
    private Typeface fontTypeface(int f){switch(f){case 1:return Typeface.create("sans-serif-light",Typeface.NORMAL);case 2:return Typeface.SERIF;case 3:return Typeface.MONOSPACE;case 4:return Typeface.create("sans-serif-black",Typeface.NORMAL);case 5:return Typeface.create("sans-serif-condensed",Typeface.NORMAL);case 6:return Typeface.create("sans-serif-rounded",Typeface.NORMAL);case 7:return Typeface.create("casual",Typeface.NORMAL);default:return Typeface.create("sans-serif-medium",Typeface.NORMAL);}}
        private GradientDrawable wallpaperBackground(){int[] colors=wallpaperPaletteEnabled?WidgetEngine.previewWallpaperSceneColors(this):new int[]{0xff193d42,0xff426f6b,0xffa2aaa0};GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,colors);d.setCornerRadius(dp(18));return d;}
    private int cornerRadius(){switch(panelTreatment){case 1:return 22;case 2:return 5;case 3:return 82;default:return 28;}}
    private int surfaceChoice(){if(panelTreatment==5)return 5;if(panelTreatment==6)return 6;if(transparent&&panelTreatment>=4)return 5;if(transparent)return 6;return Math.max(0,Math.min(4,panelTreatment));}
    private void setSurface(int value){if(value==5){panelTreatment=5;transparent=true;}else if(value==6){panelTreatment=6;transparent=true;}else{boolean enteringGlass=value==4&&panelTreatment!=4;panelTreatment=Math.max(0,Math.min(4,value));transparent=false;if(enteringGlass&&opacity>190){opacity=145;if(opacityBar!=null)opacityBar.setProgress(opacity);}}}
    private String percentage(int alpha){return Math.round(alpha*100f/255)+"%";}
    private void setEnabledTree(View view,boolean enabled){view.setEnabled(enabled);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)setEnabledTree(group.getChildAt(i),enabled);}}
    private void buildGlassPresetChoices(LinearLayout root,int ink){
        LinearLayout section=col();glassPresetSection=section;section.setPadding(0,dp(3),0,dp(3));root.addView(section);addSection(section,"GLASS PRESETS · APPLY, THEN CUSTOMIZE");glassPresetStatus=txt("",11,DataStore.accent(this),true);section.addView(glassPresetStatus,new LinearLayout.LayoutParams(-1,dp(24)));
        HorizontalScrollView scroller=new HorizontalScrollView(this);scroller.setHorizontalScrollBarEnabled(false);scroller.setClipToPadding(false);LinearLayout choices=row();choices.setPadding(dp(2),dp(3),dp(8),dp(5));scroller.addView(choices);section.addView(scroller,new LinearLayout.LayoutParams(-1,dp(82)));glassPresetTiles.clear();
        for(int i=0;i<GlassPreset.NAMES.length;i++){final int preset=i;LinearLayout tile=col();tile.setGravity(Gravity.CENTER_VERTICAL);tile.setPadding(dp(10),dp(7),dp(10),dp(7));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(138),dp(70));if(i>0)p.leftMargin=dp(7);choices.addView(tile,p);TextView name=txt(GlassPreset.NAMES[i],11,ink,true);name.setMaxLines(2);tile.addView(name);TextView note=txt(GlassPreset.NOTES[i],9,dark?0xffaabbb5:0xff5d7069,false);note.setMaxLines(2);tile.addView(note);tile.setOnClickListener(v->{glassPreset=preset;glassCustomized=false;panelTreatment=4;transparent=false;background=GlassPreset.widgetBase(preset);opacity=GlassPreset.widgetOpacity(preset);glassFinish=GlassPreset.FINISH[preset];textColor=Color.WHITE;if(surfaceSpinner!=null)surfaceSpinner.setSelection(4);if(opacityBar!=null)opacityBar.setProgress(opacity);if(glassBar!=null)glassBar.setProgress(glassFinish);refreshGlassPresetTiles(ink);syncPreview();pulsePreview();});glassPresetTiles.add(tile);}
        refreshGlassPresetTiles(ink);
    }
    private void refreshGlassPresetTiles(int ink){for(int i=0;i<glassPresetTiles.size();i++){LinearLayout tile=(LinearLayout)glassPresetTiles.get(i);int color=glassPreset==i?DataStore.accent(this):(dark?0xff14211f:0xfff2f6f4);GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(dp(14));if(glassPreset==i)bg.setStroke(dp(1),DataStore.accent(this));tile.setBackground(bg);int text=glassPreset==i?Color.WHITE:ink;for(int j=0;j<tile.getChildCount();j++)((TextView)tile.getChildAt(j)).setTextColor(j==0?text:(glassPreset==i?0xfff2f3f1:(dark?0xffaabbb5:0xff5d7069)));}}
    private void syncPreview(){
        updateContrast();if(widgetPreview==null)return;
        WidgetEngine.PreviewStyle style=new WidgetEngine.PreviewStyle();
        style.textColor=textColor;style.background=background;style.opacity=opacity;style.font=font;style.size=size;
        style.dateFormat=dateFormat;style.alarmDetail=alarmDetail;style.alignment=alignment;style.panelTreatment=panelTreatment;
        style.layoutDensity=layoutDensity;style.layoutPriority=layoutPriority;style.glassFinish=glassFinish;style.glassPreset=glassPreset;
        style.transparent=transparent;style.showDate=showDate;style.showAlarm=showAlarm;style.showCaption=showCaption;style.showContext=showContext;
        style.wallpaperColors=wallpaperPaletteEnabled;style.weatherEnabled=weatherEnabled;
        android.appwidget.AppWidgetProviderInfo provider=AppWidgetManager.getInstance(this).getAppWidgetInfo(id);
        if(provider!=null)widgetPreview.updateAppWidget(WidgetEngine.previewViews(this,id,provider.initialLayout,style,previewWidthDp,previewHeightDp));
        if(sizeLabel!=null)sizeLabel.setText(size+" sp");
        if(opacityLabel!=null)opacityLabel.setText("Panel opacity · "+percentage(transparent||panelTreatment>=5?0:opacity));
        boolean glass=panelTreatment==4;
        if(glassLabel!=null)glassLabel.setVisibility(glass?View.VISIBLE:View.GONE);
        if(glassBar!=null)glassBar.setVisibility(glass?View.VISIBLE:View.GONE);
        if(glassFinishLabels!=null)glassFinishLabels.setVisibility(glass?View.VISIBLE:View.GONE);if(glassPresetSection!=null)glassPresetSection.setVisibility(glass?View.VISIBLE:View.GONE);if(glassPresetStatus!=null)glassPresetStatus.setText(glassCustomized?"Editing "+GlassPreset.NAMES[GlassPreset.clamp(glassPreset)]+" · custom":"Glass preset · "+GlassPreset.NAMES[GlassPreset.clamp(glassPreset)]);
        boolean enabled=!transparent&&panelTreatment!=5&&panelTreatment!=6;
        if(opacityLabel!=null)opacityLabel.setAlpha(enabled?1f:.45f);
        if(opacityBar!=null){opacityBar.setEnabled(enabled);opacityBar.setAlpha(enabled?1f:.45f);}
        if(panelColorControls!=null){boolean colorsEnabled=enabled&&!wallpaperPaletteEnabled;panelColorControls.setAlpha(colorsEnabled?1f:.45f);setEnabledTree(panelColorControls,colorsEnabled);}if(textColorControls!=null){textColorControls.setAlpha(wallpaperPaletteEnabled?.45f:1f);setEnabledTree(textColorControls,!wallpaperPaletteEnabled);}
        if(surfaceSpinner!=null&&surfaceSpinner.getSelectedItemPosition()!=surfaceChoice())surfaceSpinner.setSelection(surfaceChoice());
    }
    private void updateContrast(){if(contrastLabel==null)return;int base;if(!transparent&&panelTreatment<5){int sceneColor=dark?0xff16211f:0xffedf2ef;float a=(panelTreatment==4?Math.max(.18f,Math.min(.92f,glassFinish/100f)):opacity/255f);base=blendColor(background,sceneColor,a);}else{int[] colors=wallpaperPaletteEnabled?WidgetEngine.previewWallpaperSceneColors(this):new int[]{0xff193d42,0xff426f6b,0xffa2aaa0};long r=0,g=0,b=0;for(int color:colors){r+=Color.red(color);g+=Color.green(color);b+=Color.blue(color);}base=Color.rgb((int)(r/colors.length),(int)(g/colors.length),(int)(b/colors.length));}double ratio=contrastRatio(textColor,base);String grade=ratio>=7?"Strong":"Readable";int color=DataStore.accent(this);if(ratio<4.5){grade="Low contrast · adjust text or panel colors";color=dark?0xffffb36b:0xffa75b24;}contrastLabel.setText(String.format(Locale.getDefault(),"Estimated text contrast · %.1f:1 · %s",ratio,grade));contrastLabel.setTextColor(color);}
    private int blendColor(int foreground,int background,float alpha){int a=Math.max(0,Math.min(255,Math.round(alpha*255)));return Color.rgb((Color.red(foreground)*a+Color.red(background)*(255-a))/255,(Color.green(foreground)*a+Color.green(background)*(255-a))/255,(Color.blue(foreground)*a+Color.blue(background)*(255-a))/255);}
    private double contrastRatio(int one,int two){double a=luminance(one),b=luminance(two);return (Math.max(a,b)+.05)/(Math.min(a,b)+.05);}
    private double luminance(int color){double r=Color.red(color)/255.0,g=Color.green(color)/255.0,b=Color.blue(color)/255.0;r=r<=.04045?r/12.92:Math.pow((r+.055)/1.055,2.4);g=g<=.04045?g/12.92:Math.pow((g+.055)/1.055,2.4);b=b<=.04045?b/12.92:Math.pow((b+.055)/1.055,2.4);return .2126*r+.7152*g+.0722*b;}
    private AlertDialog.Builder dialogBuilder(){int style=dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert;return new StudioAlertBuilder(new android.view.ContextThemeWrapper(this,style));}
    private final class StudioAlertBuilder extends AlertDialog.Builder{
        private final android.content.Context themedContext;private final AlertDialog[] dialogRef=new AlertDialog[1];
        StudioAlertBuilder(android.content.Context context){super(context);themedContext=context;}
        @Override public AlertDialog.Builder setTitle(CharSequence title){if(title==null)return super.setTitle(title);LinearLayout heading=row();heading.setPadding(dp(8),dp(2),dp(2),dp(2));TextView titleView=txt(title.toString(),18,dark?Color.WHITE:0xff18312f,true);titleView.setMaxLines(2);heading.addView(titleView,new LinearLayout.LayoutParams(0,-2,1));TextView close=txt("×",27,dark?0xffaabbb5:0xff5d7069,true);close.setGravity(Gravity.CENTER);close.setContentDescription("Close dialog");heading.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));close.setOnClickListener(v->{if(dialogRef[0]!=null)dialogRef[0].dismiss();});super.setCustomTitle(heading);return this;}
        @Override public AlertDialog.Builder setTitle(int titleId){return setTitle(themedContext.getText(titleId));}
        @Override public AlertDialog create(){AlertDialog dialog=super.create();dialogRef[0]=dialog;dialog.setCanceledOnTouchOutside(true);android.view.Window window=dialog.getWindow();if(window!=null){android.graphics.drawable.Drawable panel=shape(dark?0xff1b2926:0xfffcfdfc,24,true);window.setBackgroundDrawable(panel);}return dialog;}
        @Override public AlertDialog show(){AlertDialog dialog=create();dialog.show();return dialog;}
    }
    private void save(){if(weatherEnableBox!=null)weatherEnabled=weatherEnableBox.isChecked();if(weatherCityInput!=null)weatherCity=weatherCityInput.getText().toString().trim();String k="widget_"+id+"_";SharedPreferences prefs=DataStore.prefs(this);boolean wasConfigured=prefs.getBoolean(k+"configured",false);prefs.edit().putBoolean(k+"configured",true).putInt(k+"text_color",textColor).putInt(k+"background",background).putInt(k+"opacity",opacity).putInt(k+"font",font).putFloat(k+"size",size).putBoolean(k+"transparent",transparent).putBoolean(k+"show_date",showDate).putBoolean(k+"show_alarm",showAlarm).putBoolean(k+"show_caption",showCaption).putBoolean(k+"show_context",showContext).putInt(k+"date_format",dateFormat).putInt(k+"alarm_detail",alarmDetail).putInt(k+"alignment",alignment).putInt(k+"panel_treatment",panelTreatment).putInt(k+"layout_density",layoutDensity).putInt(k+"layout_priority",layoutPriority).putInt(k+"glass_finish",glassFinish).putInt(k+"glass_preset",glassPreset).putBoolean(k+"glass_customized",glassCustomized).putBoolean(k+"wallpaper_colors",wallpaperPaletteEnabled).putBoolean(k+"weather_enabled",weatherEnabled).putString(k+"weather_city",weatherCityInput==null?weatherCity:weatherCityInput.getText().toString().trim()).putInt(k+"weather_interval",weatherIntervalSpinner==null?weatherInterval:weatherIntervalSpinner.getSelectedItemPosition()==0?30:weatherIntervalSpinner.getSelectedItemPosition()==2?120:60).apply();WeatherRefresh.configure(this,id,weatherEnabled);WidgetEngine.refreshWidget(this,id);DataStore.log(this,"Widget",wasConfigured?"Widget style updated":"Widget added and styled",WidgetEngine.designName(this,id)+" · " +(panelTreatment==4?"TicTic glass":panelTreatment==5?"outline":panelTreatment==6?"no panel":"custom style"));Intent result=new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);setResult(RESULT_OK,result);finish();}
